select date_trunc('month', opened_date) as activity_month, case when balance >= 86000 then 'PREMIUM' else 'STANDARD' end as balance_tier, stddev_samp(balance) as balance_stddev, size(collect_set(status)) as num_status, percentile_approx(balance, array(0.25, 0.5, 0.75)) as balance_quartiles, round(avg(balance), 2) as avg_balance, stddev_samp(balance) as balance_stddev_2, count(distinct account_type) as distinct_account_types, grouping_id() as grouping_level from accounts group by grouping sets ((date_trunc('month', opened_date), case when balance >= 86000 then 'PREMIUM' else 'STANDARD' end), (date_trunc('month', opened_date)), ()) order by avg_balance desc;
